.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(120%);
  background: var(--accent);
  color: var(--accent-ink);
  padding: 12px 20px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--shadow);
  transition: transform .3s ease;
  z-index: 200;
}
.toast.show { transform: translateX(-50%) translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { aspect-ratio: 16/10; max-width: 600px; }
  .products { grid-template-columns: repeat(3, 1fr); }
  .categories { grid-template-columns: repeat(3, 1fr); }
  .editorial { grid-template-columns: repeat(2, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .nav, .search, .topbar-links { display: none; }
  .menu-toggle { display: grid; }
  .products { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .editorial { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .hero { padding: 40px 0 60px; }
  .hero-stats { gap: 20px; }
  section.block { padding: 56px 0; }
  .newsletter-wrap { padding: 40px 24px; }
  .newsletter-form { flex-direction: column; }
  .product-body { padding: 12px; }
  .product-name { font-size: 14px; }
}
