arguments.file_text:
:root {
  --bg: #0a0a0c;
  --bg-elev: #14141a;
  --bg-elev-2: #1c1c24;
  --border: #26262f;
  --border-strong: #3a3a47;
  --text: #f5f5f7;
  --text-muted: #a1a1ab;
  --text-dim: #6b6b78;
  --accent: #c7f23d;
  --accent-hover: #d4ff4d;
  --accent-ink: #0a0a0c;
  --danger: #ff5757;
  --success: #4ade80;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  --maxw: 1240px;
  --focus: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent);
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: 6px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 12px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  z-index: 1000;
}
.skip-link:focus { top: 12px; }

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- Top bar ---------- */
.topbar {
  background: #000;
  color: var(--text-muted);
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}
.topbar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
  gap: 16px;
}
.topbar a:hover { color: var(--text); }
.topbar-links { display: flex; gap: 20px; }

/* ---------- Header ---------- */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10, 10, 12, 0.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
  gap: 24px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.02em;
}
.brand-mark {
  width: 30px; height: 30px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  display: grid; place-items: center;
  font-weight: 900;
}
.nav { display: flex; gap: 4px; }
.nav a {
  padding: 8px 14px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  transition: color .15s, background .15s;
}
.nav a:hover, .nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions { display: flex; align-items: center; gap: 6px; }

.icon-btn {
  width: 40px; height: 40px;
  display: grid; place-items: center;
  border-radius: 10px;
  color: var(--text-muted);
  position: relative;
  transition: background .15s, color .15s;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 700;
  min-width: 18px; height: 18px;
  border-radius: 9px;
  display: grid; place-items: center;
  padding: 0 4px;
}

.search {
  position: relative;
  flex: 1;
  max-width: 360px;
}
.search input {
  width: 100%;
  padding: 10px 14px 10px 38px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text);
  font-size: 14px;
}
.search input::placeholder { color: var(--text-dim); }
.search input:focus { border-color: var(--accent); outline: none; box-shadow: none; }
.search svg {
  position: absolute;
  left: 12px; top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  pointer-events: none;
}

.menu-toggle { display: none; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  transition: transform .1s, background .15s, color .15s, border-color .15s;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-secondary {
  background: var(--bg-elev);
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev-2); }
.btn-ghost {
  color: var(--text);
}
.btn-ghost:hover { background: var(--bg-elev); }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 64px 0 80px;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(800px 400px at 80% 10%, rgba(199, 242, 61, 0.12), transparent 60%),
    radial-gradient(600px 400px at 10% 80%, rgba(120, 119, 198, 0.12), transparent 60%);
  pointer-events: none;
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 56px;
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 24px;
}
.hero-eyebrow .dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--accent);
}
.hero h1 {
  font-size: clamp(40px, 6vw, 72px);
  line-height: 1.02;
  letter-spacing: -0.03em;
  margin: 0 0 20px;
  font-weight: 800;
}
.hero h1 .accent { color: var(--accent); font-style: italic; font-family: 'Playfair Display', Georgia, serif; font-weight: 500; }
.hero p.lede {
  font-size: 18px;
  color: var(--text-muted);
  max-width: 480px;
  margin: 0 0 32px;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
  padding-top: 32px;
  border-top: 1px solid var(--border);
}
.stat-num {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.02em;
  display: block;
}
.stat-label {
  font-size: 13px;
  color: var(--text-muted);
}

.hero-visual {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(135deg, #1c1c24, #0a0a0c);
  border: 1px solid var(--border);
}
.hero-visual img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.hero-card {
  position: absolute;
  background: rgba(20, 20, 26, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-card.left { bottom: 24px; left: 24px; }
.hero-card.right {
  top: 24px; right: 24px;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
.hero-card .price {
  font-weight: 700;
  font-size: 18px;
}
.hero-card .label {
  font-size: 12px;
  color: var(--text-muted);
}
.hero-card .pill {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 999px;
}

/* ---------- Marquee ---------- */
.marquee {
  border-block: 1px solid var(--border);
  background: var(--bg-elev);
  padding: 18px 0;
  overflow: hidden;
  white-space: nowrap;
}
.marquee-track {
  display: inline-flex;
  gap: 56px;
  animation: scroll 30s linear infinite;
  padding-right: 56px;
}
.marquee-item {
  font-size: 14px;
  color: var(--text-muted);
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 56px;
}
.marquee-item::after {
  content: "✦";
  color: var(--accent);
  font-size: 12px;
}
@keyframes scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@media (prefers-reduced-motion: reduce) {
  .marquee-track { animation: none; }
}

/* ---------- Section ---------- */
section.block { padding: 80px 0; }
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 40px;
  gap: 24px;
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: clamp(28px, 4vw, 44px);
  margin: 0 0 8px;
  letter-spacing: -0.025em;
  font-weight: 700;
}
.section-header p {
  margin: 0;
  color: var(--text-muted);
  max-width: 480px;
}
.section-eyebrow {
  font-size: 12px;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 12px;
  display: block;
}

/* ---------- Categories ---------- */
.categories {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.cat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  text-align: center;
  transition: transform .15s, border-color .15s, background .15s;
  font-size: 13px;
  font-weight: 500;
}
.cat-card:hover {
  transform: translateY(-2px);
  border-color: var(--accent);
  background: var(--bg-elev-2);
}
.cat-icon {
  width: 44px; height: 44px;
  background: var(--bg-elev-2);
  border-radius: 12px;
  display: grid; place-items: center;
  color: var(--accent);
}

/* ---------- Product Grid ---------- */
.filter-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 28px;
  padding: 6px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  width: fit-content;
}
.filter-tab {
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  transition: background .15s, color .15s;
}
.filter-tab:hover { color: var(--text); }
.filter-tab[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
}

.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .2s, border-color .2s;
  position: relative;
}
.product:hover {
  transform: translateY(-4px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1;
  overflow: hidden;
  background: linear-gradient(135deg, #1c1c24, #0a0a0c);
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s;
}
.product:hover .product-media img { transform: scale(1.05); }
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.product-tag.new { background: #fff; }
.product-tag.sale { background: var(--danger); color: #fff; }
.wishlist {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  background: rgba(10,10,12,0.7);
  backdrop-filter: blur(8px);
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--text);
  transition: background .15s, color .15s;
}
.wishlist:hover { background: var(--bg); color: var(--danger); }
.wishlist[aria-pressed="true"] { color: var(--danger); }

.product-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 8px;
}
.product-cat {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
  font-weight: 600;
}
.product-name {
  font-weight: 600;
  font-size: 15px;
  margin: 0;
  line-height: 1.3;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }
.product-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 8px;
}
.price-block { display: flex; align-items: baseline; gap: 8px; }
.price-now { font-weight: 700; font-size: 17px; }
.price-was {
  color: var(--text-dim);
  font-size: 13px;
  text-decoration: line-through;
}
.add-btn {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--bg-elev-2);
  display: grid; place-items: center;
  color: var(--text);
  transition: background .15s, color .15s;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); }

/* ---------- Deals ---------- */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 20px;
}
.deal {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid var(--border);
  min-height: 360px;
  display: flex;
  align-items: flex-end;
  padding: 32px;
  isolation: isolate;
}
.deal::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10,10,12,0) 30%, rgba(10,10,12,0.9) 100%);
  z-index: -1;
}
.deal img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  z-index: -2;
}
.deal-content { max-width: 360px; }
.deal-tag {
  display: inline-block;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  font-size: 12px;
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.deal h3 {
  font-size: 28px;
  margin: 0 0 10px;
  letter-spacing: -0.02em;
  font-weight: 700;
}
.deal p { color: var(--text-muted); margin: 0 0 18px; }

.countdown {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}
.cd-unit {
  background: rgba(10,10,12,0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 10px 12px;
  text-align: center;
  min-width: 56px;
}
.cd-num { font-size: 22px; font-weight: 700; line-height: 1; }
.cd-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 4px;
}

/* ---------- Editorial ---------- */
.editorial {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color .15s, transform .2s;
}
.article:hover { border-color: var(--border-strong); transform: translateY(-3px); }
.article-media {
  aspect-ratio: 16/10;
  overflow: hidden;
  background: var(--bg-elev-2);
}
.article-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s;
}
.article:hover .article-media img { transform: scale(1.05); }
.article-body { padding: 22px; flex: 1; display: flex; flex-direction: column; gap: 12px; }
.article-meta {
  display: flex;
  gap: 12px;
  align-items: center;
  font-size: 12px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}
.article-meta .cat { color: var(--accent); }
.article h3 {
  font-size: 20px;
  margin: 0;
  line-height: 1.25;
  letter-spacing: -0.01em;
}
.article p {
  color: var(--text-muted);
  margin: 0;
  font-size: 14px;
}
.article-link {
  margin-top: auto;
  font-weight: 600;
  font-size: 14px;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.article-link:hover { gap: 10px; }

/* ---------- Newsletter ---------- */
.newsletter-wrap {
  background: linear-gradient(135deg, #1c1c24, #0a0a0c);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 64px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.newsletter-wrap::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(600px 300px at 50% 0%, rgba(199, 242, 61, 0.1), transparent 70%);
  pointer-events: none;
}
.newsletter-wrap h2 {
  font-size: clamp(28px, 4vw, 40px);
  margin: 0 0 12px;
  letter-spacing: -0.02em;
  position: relative;
}
.newsletter-wrap p {
  color: var(--text-muted);
  max-width: 460px;
  margin: 0 auto 28px;
  position: relative;
}
.newsletter-form {
  display: flex;
  gap: 8px;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 18px;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form input:focus { border-color: var(--accent); outline: none; box-shadow: none; }
.newsletter-status {
  margin-top: 16px;
  font-size: 14px;
  color: var(--success);
  min-height: 20px;
  position: relative;
}

/* ---------- Footer ---------- */
.footer {
  background: #050507;
  border-top: 1px solid var(--border);
  padding: 64px 0 24px;
  margin-top: 80px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  margin: 0 0 18px;
  font-weight: 600;
}
.footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer ul a { color: var(--text-muted); font-size: 14px; transition: color .15s; }
.footer ul a:hover { color: var(--accent); }
.footer-about p {
  color: var(--text-muted);
  font-size: 14px;
  max-width: 320px;
  margin: 12px 0 24px;
}
.socials { display: flex; gap: 8px; }
.socials a {
  width: 38px; height: 38px;
  border-radius: 10px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: background .15s, color .15s, border-color .15s;
}
.socials a:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: var(--text-dim);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(120%);
  background: var(--accent);
  color: var(--accent-ink);
  padding: 12px 20px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--shadow);
  transition: transform .3s ease;
  z-index: 200;
}
.toast.show { transform: translateX(-50%) translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { aspect-ratio: 16/10; max-width: 600px; }
  .products { grid-template-columns: repeat(3, 1fr); }
  .categories { grid-template-columns: repeat(3, 1fr); }
  .editorial { grid-template-columns: repeat(2, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .nav, .search, .topbar-links { display: none; }
  .menu-toggle { display: grid; }
  .products { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .editorial { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .hero { padding: 40px 0 60px; }
  .hero-stats { gap: 20px; }
  section.block { padding: 56px 0; }
  .newsletter-wrap { padding: 40px 24px; }
  .newsletter-form { flex-direction: column; }
  .product-body { padding: 12px; }
  .product-name { font-size: 14px; }
}

