function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 38 + 1000 * 60 * 23, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const hh = Math.floor((diff / 3600000) % 24);
  const mm = Math.floor((diff / 60000) % 60);
  const ss = Math.floor((diff / 1000) % 60);
  const units = [{ n: d, l: 'Days' }, { n: hh, l: 'Hours' }, { n: mm, l: 'Min' }, { n: ss, l: 'Sec' }];
  return e('div', { className: 'countdown', role: 'timer', 'aria-label': `Offer ends in ${d} days, ${hh} hours, ${mm} minutes` },
    units.map(u => e('div', { key: u.l, className: 'cd-unit' },
      e('div', { className: 'cd-num' }, String(u.n).padStart(2, '0')),
      e('div', { className: 'cd-label' }, u.l)
    ))
  );
}

