      setStatus('Please enter a valid email address.');
      return;
    }
    setStatus(`Welcome aboard — confirmation sent to ${email}.`);
    setEmail('');
  };
  return e('section', { className: 'block', 'aria-labelledby': 'nl-title' },
    e('div', { className: 'container' },
