/* ---------- App ---------- */
function App() {
  const [cart, setCart] = useState([]);
  const [wished, setWished] = useState([]);
  const [toast, setToast] = useState({ message: '', show: false });
  const toastTimer = useRef();

  const addToCart = useCallback((p) => {
    setCart(c => [...c, p.id]);
    showToast(`Added "${p.name}" to bag`);
  }, []);

  const toggleWish = useCallback((id) => {
    setWished(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  }, []);

  const showToast = (message) => {
    setToast({ message, show: true });
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(t => ({ ...t, show: false })), 2400);
  };

  return e(Fragment, null,
    e('a', { href: '#main', className: 'skip-link' }, 'Skip to main content'),
    e(TopBar),
    e(Header, { cartCount: cart.length, wishlistCount: wished.length, onCartClick: () => showToast(`Bag has ${cart.length} item${cart.length === 1 ? '' : 's'}`) }),
    e('main', { id: 'main' },
      e(Hero, { onCta: () => document.getElementById('new')?.scrollIntoView({ behavior: 'smooth' }) }),
      e(Marquee),
      e(Categories),
      e(Featured, { onAdd: addToCart, wished, onWish: toggleWish }),
      e(Deals),
      e(Editorial),
      e(Newsletter)
    ),
    e(Footer),
    e(Toast, toast)
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(e(StrictMode, null, e(App)));

